SELECT CONCAT(warning_order_id, '') AS 'warningOrderId', IF(alarm_time IS NULL,'',DATE_FORMAT(alarm_time,'%Y-%m-%d %H:%i:%s')) as 'alarmTime', industry_code AS 'industryCode',warning_type_id AS 'warningTypeId',warning_source AS 'warningSource',tenant_id AS 'tenantId' from ${tableName} where delete_flag = '0' and user_record is not null and(
